function read_snapshot(seam: ISqlSeam): Observable<Snapshot> {
  return forkJoin({
    field: select_rows(seam, `SELECT CASE WHEN json_valid("key") AND json_type("key") = 'object' AND json_type("key", '$.fn') = 'text' AND json_type("key", '$.args') = 'array' THEN json_extract("key", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("key", '$.args')), '') || ')' ELSE "key" END AS "key", CASE WHEN json_valid("value") AND json_type("value") = 'object' AND json_type("value", '$.fn') = 'text' AND json_type("value", '$.args') = 'array' THEN json_extract("value", '$.fn') || '(' || coalesce((SELECT group_concat(value, ',') FROM json_each("value", '$.args')), '') || ')' ELSE "value" END AS "value" FROM "__txt_field" t`, rel_columns.field!, rel_column_types.field!),
    raw_doc: select_rows(seam, `SELECT "body" FROM "raw_doc" t`, rel_columns.raw_doc!, rel_column_types.raw_doc!),
  });
}

type Snapshots = { readonly decoded: Snapshot; readonly stored: Snapshot };

function read_stored_snapshot(seam: ISqlSeam): Observable<Snapshot> {
  return forkJoin({
    field: select_rows(seam, `SELECT "key", "value" FROM "field"`, rel_columns.field!, rel_column_types.field!),
    raw_doc: select_rows(seam, `SELECT "body" FROM "raw_doc"`, rel_columns.raw_doc!, rel_column_types.raw_doc!),
  });
}

function read_snapshots(seam: ISqlSeam): Observable<Snapshots> {
  return forkJoin({ decoded: read_snapshot(seam), stored: read_stored_snapshot(seam) });
}

